<?php require_once __DIR__.'/app/bootstrap.php'; if($_SERVER['REQUEST_METHOD']!=='POST') redirect('contactus.php'); $m=['name','email','subject','message']; foreach($m as $f) if(trim($_POST[$f]??'')===''){$_SESSION['flash']=['type'=>'danger','msg'=>'Please complete all fields.'];redirect('contactus.php');} $items=read_data('messages'); $items[]=['id'=>next_id($items),'name'=>trim($_POST['name']),'email'=>trim($_POST['email']),'subject'=>trim($_POST['subject']),'message'=>trim($_POST['message']),'date'=>date('Y-m-d H:i:s'),'status'=>'Unread']; write_data('messages',$items); $_SESSION['flash']=['type'=>'success','msg'=>'Message sent successfully.']; redirect('contactus.php');